function areSentencesSimilarTwo(sentence1, sentence2, similarPairs) {
  if (sentence1.length !== sentence2.length) {
    return false;
  }
  const parent = new Map();

  const find = (word) => {
    if (!parent.has(word)) {
      parent.set(word, word);
    }
    while (parent.get(word) !== word) {
      parent.set(word, parent.get(parent.get(word)));
      word = parent.get(word);
    }
    return word;
  };

  for (const [first, second] of similarPairs) {
    const rootA = find(first);
    const rootB = find(second);
    if (rootA !== rootB) {
      parent.set(rootA, rootB);
    }
  }

  for (let i = 0; i < sentence1.length; i++) {
    if (find(sentence1[i]) !== find(sentence2[i])) {
      return false;
    }
  }
  return true;
}

