function areSentencesSimilarTwo(sentence1, sentence2, similarPairs) {
  if (sentence1.length !== sentence2.length) return false;
  const graph = {};
  const link = (a, b) => { (graph['#' + a] ||= []).push(b); };
  for (const [x, y] of similarPairs) { link(x, y); link(y, x); }
  const reachable = (from, to) => {
    const seen = new Set([from]);
    const stack = [from];
    while (stack.length) {
      const word = stack.pop();
      if (word === to) return true;
      for (const next of graph['#' + word] || []) if (!seen.has(next)) { seen.add(next); stack.push(next); }
    }
    return false;
  };
  return sentence1.every((word, i) => reachable(word, sentence2[i]));
}

