function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  let vocab;
  if (small) {
    vocab = ['a', 'b', 'c', 'A', 'great', 'good', 'fine', 'drama', 'Fine', 'x'].slice(0, 3 + Math.floor(rand() * 8));
  } else {
    const words = new Set();
    while (words.size < 400) {
      const length = 1 + Math.floor(rand() * 20);
      let word = '';
      for (let k = 0; k < length; k++) word += letters[Math.floor(rand() * letters.length)];
      words.add(word);
    }
    vocab = [...words];
  }
  const groupCount = small ? 1 + Math.floor(rand() * 3) : 20 + Math.floor(rand() * 40);
  const members = Array.from({ length: groupCount }, () => []);
  const groupOf = new Map();
  for (const word of vocab) {
    const g = Math.floor(rand() * groupCount);
    groupOf.set(word, g);
    members[g].push(word);
  }
  // Large inputs link every group fully; half of them then get one position from another group.
  const linkChance = small ? 0.6 : 1;
  const pairs = [];
  const addPair = (a, b) => pairs.push(rand() < 0.5 ? [a, b] : [b, a]);
  for (const group of members) {
    for (let k = 1; k < group.length; k++) if (rand() < linkChance) addPair(group[k], group[Math.floor(rand() * k)]);
  }
  const extra = small ? Math.floor(rand() * 3) : 1500 - pairs.length;
  for (let k = 0; k < extra; k++) {
    const a = pick(vocab);
    const b = small ? pick(vocab) : pick(members[groupOf.get(a)]);
    addPair(a, b);
  }
  for (let k = pairs.length - 1; k > 0; k--) {
    const j = Math.floor(rand() * (k + 1));
    [pairs[k], pairs[j]] = [pairs[j], pairs[k]];
  }
  const length = small ? 1 + Math.floor(rand() * 5) : 1000;
  const sentence1 = Array.from({ length }, () => pick(vocab));
  const faithful = small ? 0.7 : 1;
  const sentence2 = sentence1.map(word => rand() < faithful ? pick(members[groupOf.get(word)]) : pick(vocab));
  if (!small && rand() < 0.5) {
    const i = Math.floor(rand() * length);
    const others = vocab.filter(word => groupOf.get(word) !== groupOf.get(sentence1[i]));
    if (others.length) sentence2[i] = pick(others);
  }
  if (small && rand() < 0.1) {
    if (sentence2.length > 1 && rand() < 0.5) sentence2.pop();
    else sentence2.push(pick(vocab));
  }
  return [sentence1, sentence2, pairs];
}
